  publish_file: {
    tiers: ["lead","member"],
    blocking: [],
    requires: null,
    description: "Publish a file you made (HTML prototype, Markdown doc, PDF, text, JSON, CSV) as a project deliverable. The platform uploads it from your working directory and hosts it; people view it on the Deliverables page and their comments come back to you as messages. A directory with index.html is published as a small site (it may contain images and other assets). Pass deliverable_id to publish a new version of an earlier deliverable. Screenshots and images are not deliverables: a lone PNG/JPG/GIF/WebP is saved as an attachment in your thread's messages instead (no deliverable, cannot be a new version), and a lone SVG is refused. To put an image in a report, publish it in one directory with the report's index.html, or inline it in the HTML (an SVG can be written straight into the HTML); Markdown cannot show images. Cite an attachment (its id or URL) only in your written report.",
    input_schema: {"description":"Publish a file you made (HTML prototype, Markdown doc, PDF, text, JSON, CSV) as a project deliverable. The platform uploads it from your working directory and hosts it; people view it on the Deliverables page and their comments come back to you as messages. A directory with index.html is published as a small site (it may contain images and other assets). Pass deliverable_id to publish a new version of an earlier deliverable. Screenshots and images are not deliverables: a lone PNG/JPG/GIF/WebP is saved as an attachment in your thread's messages instead (no deliverable, cannot be a new version), and a lone SVG is refused. To put an image in a report, publish it in one directory with the report's index.html, or inline it in the HTML (an SVG can be written straight into the HTML); Markdown cannot show images. Cite an attachment (its id or URL) only in your written report.","type":"object","required":["path","kind","title"],"additionalProperties":false,"properties":{"path":{"description":"File (or directory with index.html) inside your working directory, relative to it.","type":"string","minLength":1,"maxLength":500},"kind":{"description":"design for prototypes and visual designs, doc for documents and specs; also slides, dashboard, board, data.","type":"string","minLength":1,"maxLength":32,"examples":["design","doc","slides","dashboard","data"]},"title":{"type":"string","minLength":1,"maxLength":300},"deliverable_id":{"description":"An earlier deliverable of this project published with publish_file; the file becomes its next version.","type":"string","pattern":"^dl_[A-Za-z0-9]+$"}}},
  },
